sys_script_include.script:
var IngestionLayer = Class.create();
IngestionLayer.prototype = {
    initialize: function() {},
    processIncomingCase: function(payload) {
        var caseGr = new GlideRecord('sn_customerservice_case');
        caseGr.initialize();
        caseGr.short_description = payload.short_description;
        caseGr.description = payload.description;
        caseGr.contact = payload.contact_id;
        new CaseCategorizationEngine().categorize(caseGr);
        return caseGr.insert();
    },
    type: 'IngestionLayer'
};

var CaseCategorizationEngine = Class.create();
CaseCategorizationEngine.prototype = {
    initialize: function() {},
    categorize: function(current) {
        var text = (current.short_description + " " + current.description).toLowerCase();
        var keywords = {
            "hardware": ["laptop", "monitor", "keyboard", "mouse", "printer", "battery", "hardware", "screen", "tablet", "docking", "webcam", "charger", "display", "hdd", "ram"],
            "network": ["wifi", "internet", "vpn", "connection", "network", "router", "dns", "ip", "ethernet", "firewall", "bandwidth", "latency", "signal", "port"],
            "software": ["office", "outlook", "excel", "windows", "software", "install", "update", "drivers", "browser", "adobe", "teams", "slack", "zoom", "java"],
            "security": ["password", "access", "lockout", "mfa", "permission", "unauthorized", "phishing", "breach", "virus", "malware", "token", "encryption", "firewall", "leak"],
            "account": ["login", "profile", "account", "ad", "username", "sso", "portal", "onboarding", "offboarding", "credentials", "idm", "ldap"],
            "infrastructure": ["server", "outage", "database", "cloud", "aws", "azure", "vcenter", "storage", "virtual", "cluster", "backup", "recovery", "linux", "unix"]
        };

        var category = "Other";
        var maxCount = 0;
        for (var cat in keywords) {
            var count = 0;
            keywords[cat].forEach(function(word) {
                if (text.indexOf(word) > -1) count++;
            });
            if (count > maxCount) {
                maxCount = count;
                category = cat.charAt(0).toUpperCase() + cat.slice(1);
            }
        }

        current.category = category;
        if (text.indexOf('outage') > -1 || text.indexOf('breach') > -1 || text.indexOf('critical') > -1 || text.indexOf('urgent') > -1 || text.indexOf('emergency') > -1) {
            current.priority = 1;
            current.impact = 1;
            current.urgency = 1;
        } else if (maxCount > 2 || text.indexOf('important') > -1) {
            current.priority = 2;
            current.impact = 2;
            current.urgency = 2;
        } else {
            current.priority = 3;
            current.impact = 3;
            current.urgency = 3;
        }
    },
    type: 'CaseCategorizationEngine'
};

var AgentMatchingUtil = Class.create();
AgentMatchingUtil.prototype = {
    initialize: function() {},
    findBestAgent: function(caseGr) {
        var agents = new GlideRecord('sys_user');
        agents.addQuery('active', true);
        agents.addEncodedQuery('roles=sn_customerservice.agent');
        agents.query();

        var bestAgent = null;
        var highestScore = -1;

        while (agents.next()) {
            var score = 0;
            // 1. Skill Match (40%)
            var skills = new GlideRecord('sys_user_has_skill');
            skills.addQuery('user', agents.sys_id);
            skills.addQuery('skill.name', 'CONTAINS', caseGr.category);
            skills.query();
            if (skills.hasNext()) score += 40;

            // 2. Workload (30%)
            var activeCases = new GlideAggregate('sn_customerservice_case');
            activeCases.addQuery('assigned_to', agents.sys_id);
            activeCases.addQuery('active', true);
            activeCases.addAggregate('COUNT');
            activeCases.query();
            var count = 0;
            if (activeCases.next()) count = activeCases.getAggregate('COUNT');
            score += Math.max(0, 30 - (count * 5));

            // 3. Availability (20%)
            if (agents.introduction != 'away' && agents.active) score += 20;

            // 4. Certification (10%)
            if (agents.vip || agents.title.indexOf('Senior') > -1) score += 10;

            if (score > highestScore) {
                highestScore = score;
                bestAgent = agents.getUniqueValue();
            }
        }
        return bestAgent;
    },
    type: 'AgentMatchingUtil'
};

var SLACalculator = Class.create();
SLACalculator.prototype = {
    initialize: function() {},
    calculateRisk: function(caseGr) {
        var sla = new GlideRecord('task_sla');
        sla.addQuery('task', caseGr.sys_id);
        sla.addQuery('active', true);
        sla.query();
        while (sla.next()) {
            if (sla.percentage > 80) return true;
        }
        return false;
    },
    type: 'SLACalculator'
};

var AuditLogger = Class.create();
AuditLogger.prototype = {
    initialize: function() {},
    logChange: function(caseGr, message) {
        var log = new GlideRecord('sys_audit');
        log.initialize();
        log.tablename = 'sn_customerservice_case';
        log.documentkey = caseGr.sys_id;
        log.fieldname = 'work_notes';
        log.newvalue = message;
        log.user = gs.getUserName();
        log.insert();
    },
    type: 'AuditLogger'
};

var EscalationManager = Class.create();
EscalationManager.prototype = {
    initialize: function() {},
    checkEscalations: function() {
        var cases = new GlideRecord('sn_customerservice_case');
        cases.addQuery('active', true);
        cases.addQuery('state', '!=', 3);
        cases.query();

        while (cases.next()) {
            var now = new GlideDateTime();
            var created = new GlideDateTime(cases.sys_created_on);
            var ageHours = (now.getNumericValue() - created.getNumericValue()) / 3600000;

            if (cases.priority == 1 && ageHours > 2) this._escalate(cases, 'ESC-001');
            else if (cases.priority == 2 && ageHours > 4) this._escalate(cases, 'ESC-002');
            else if (cases.reassignment_count > 3) this._escalate(cases, 'ESC-003');
            else if (new SLACalculator().calculateRisk(cases)) this._escalate(cases, 'ESC-004');
            else if (cases.contact.vip && ageHours > 1) this._escalate(cases, 'ESC-005');
            else if (ageHours > 0.5 && !cases.assigned_to) this._escalate(cases, 'ESC-006');
            else if (cases.short_description.toLowerCase().indexOf('escalate') > -1) this._escalate(cases, 'ESC-007');
        }
    },
    _escalate: function(caseGr, ruleId) {
        caseGr.escalation = 1;
        if (ruleId == 'ESC-001') caseGr.escalation = 2;
        caseGr.work_notes = "Auto-escalated by rule: " + ruleId;
        caseGr.update();
        new AuditLogger().logChange(caseGr, "System Escalation: " + ruleId);
    },
    type: 'EscalationManager'
};

sys_script.script:
(function executeRule(current, previous) {
    new CaseCategorizationEngine().categorize(current);
    var agent = new AgentMatchingUtil().findBestAgent(current);
    if (agent) current.assigned_to = agent;
})(current, previous);
